import sys
sys.path.insert(0,'/downloads/fiqh-alruh-source/gen')
import lib
head,W,R,S=lib.load()
def E_(i,t,d,ref): return {'id':i,'t':t,'d':d,'kind':'الموسوعة','ref':ref}
Q=' والحديث المنقول فيها لم يُراجع هنا في أصله ولم تُحكم درجته.'
add={
'tashmit':[
('why',E_('m3','نعمة متتابعة في زمن يسير','نقلت الموسوعة عن ابن أبي جمرة قوله: في الحديث دليل على عظيم نعمة الله على العاطس، يؤخذ ذلك مما رُتب عليه من الخير. فقد أذهب الله عنه الضرر بنعمة العطس، ثم شرع له الحمد الذي يثاب عليه، ثم الدعاء بالخير بعد الدعاء بالخير، وشرع هذه النعم المتواليات في زمن يسير فضلاً منه وإحساناً. ومعنى قول المشمّت: يرحمك الله، عنده: جعل الله لك ذلك لتدوم لك السلامة، وفيه تنبيه للعاطس على طلب الرحمة والتوبة من الذنب. وهذا شرح ابن أبي جمرة للحديث كما نقلته الموسوعة، وليس حكماً.','الموسوعة الفقهية الكويتية، تشميت، المجلد 12: https://muslim-library.com/keoj/volume/12/7559/')),
('why',E_('m4','حكمة التشميت','نقلت الموسوعة عن ابن دقيق العيد أن من فوائد التشميت تحصيل المودة والتأليف بين المسلمين، وتأديب العاطس بكسر النفس عن الكبر والحمل على التواضع، لما في ذكر الرحمة من الإشعار بالذنب الذي لا يعرى عنه أكثر المكلفين. وهذا ما ذكره ابن دقيق العيد من الفوائد، وهو غير نص الحديث.','الموسوعة الفقهية الكويتية، تشميت، المجلد 12: https://muslim-library.com/keoj/volume/12/7560/')),
('why',E_('m5','أدب العاطس: خفض الصوت وتغطية الوجه','تذكر الموسوعة من آداب العاطس أن يخفض صوته بالعطس ويرفعه بالحمد، وأن يغطي وجهه لئلا يبدو من فيه أو أنفه ما يؤذي جليسه، وألا يلوي عنقه يمنة ولا يسرة. ونقلت عن ابن العربي: الحكمة في خفض الصوت أن رفعه إزعاج للأعضاء، وفي تغطية الوجه أنه لو بدر منه شيء آذى جليسه، ولو لوى عنقه صيانة لجليسه لم يأمن من الالتواء. وذكرت أن النبي ﷺ كان إذا عطس وضع يده أو ثوبه على فيه وخفض أو غض بها صوته.'+Q,'الموسوعة الفقهية الكويتية، تشميت، المجلد 12: https://muslim-library.com/keoj/volume/12/7559/ و https://muslim-library.com/keoj/volume/12/7560/')),
],
'rawatib':[
('why',E_('m3','لماذا سُميت رواتب','تذكر الموسوعة أن الراتبة من رَتَبَ الشيءُ رُتُوباً إذا استقر ودام، وأن السنن الرواتب سميت بذلك لمشروعية المواظبة عليها. وتنقل عن الشافعية أن الرواتب هي السنن التابعة لغيرها أو المتوقفة على غيرها أو على ما له وقت معين، وأن الفقهاء يطلقونها على الصلوات المسنونة قبل الفرائض وبعدها لأنه لا يشرع أداؤها وحدها بدون تلك الفرائض. وهذا شرح للتسمية والمعنى كما في الموسوعة، وعدد الركعات وخلاف المذاهب في الخلاف.','الموسوعة الفقهية الكويتية، السنن الرواتب، المجلد 25: https://muslim-library.com/keoj/volume/25/16678/ و https://muslim-library.com/keoj/volume/25/16677/')),
],
'adabakl':[
('why',E_('m3','الأكل باليمين وفيما يليك','تذكر الموسوعة أنه ينبغي للمسلم أن يأكل بيمينه ولا يأكل بشماله، وتروي عن ابن عمر أن النبي ﷺ قال: لا يأكلن أحدكم بشماله ولا يشربن بها، فإن الشيطان يأكل بشماله ويشرب بها. وتقول إن الحديث يشير إلى أن الإنسان ينبغي أن يتجنب الأفعال التي تشبه أفعال الشيطان، وإن كان عذر من مرض أو جراحة أو غيره فلا كراهة في الشمال. وفي الأكل مما يليه تقول الموسوعة: يسن أن يأكل الإنسان مما يليه ولا تمتد يده إلى ما يلي الآخرين ولا إلى وسط الطعام، لأن أكل المرء من موضع صاحبه سوء عشرة وترك مروءة وقد يتقذره صاحبه، وتذكر حديث ابن عباس: البركة تنزل وسط الطعام فكلوا من حافتيه ولا تأكلوا من وسطه.'+Q,'الموسوعة الفقهية الكويتية، أكل، المجلد 6: https://muslim-library.com/keoj/volume/6/3793/')),
],
}
cnt=0
for C in W:
  for L in C['lessons']:
    if L['id'] in add:
      ids={x['id'] for g in L['meaning'].values() for x in g}
      for g,it in add[L['id']]:
        if it['id'] in ids:
          n=max(int(i[1:]) for i in ids)+1; it['id']='m%d'%n
        ids.add(it['id']); L['meaning'][g].append(it); cnt+=1
lib.save(head,W,R,S);print(cnt)
